        const setupSlider = (id) => {
            const $el = dialog.find(id);
            let autoOpened = false;
            let transparencyTimer = null;
            const end = (e) => {
                if (transparencyTimer) { clearTimeout(transparencyTimer); transparencyTimer = null; }
                dialog.removeClass('acu-transparent-mode');
                $el.closest('.acu-control-row').removeClass('acu-active-control');
                if (e && e.type !== 'change') {
                     const nativeEvent = e.originalEvent || e;
                     if (e.target && e.target.releasePointerCapture && nativeEvent.pointerId) {
                         try { e.target.releasePointerCapture(nativeEvent.pointerId); } catch(err){}
                     }
                }
                $el.off('pointerup pointercancel', end);
                if (autoOpened) { closePanel(); autoOpened = false; }
            };
            $el.on('pointerdown', function(e) {
                const nativeEvent = e.originalEvent || e;
                if (this.setPointerCapture && nativeEvent.pointerId) {
                     this.setPointerCapture(nativeEvent.pointerId);
                }
                if (!$('#acu-data-area').hasClass('visible')) {
                    const $last = $('.acu-nav-btn[data-table]').not('[data-table=\"acu_tab_dashboard_home\"]').last();
                    if($last.length) { $last.click(); autoOpened = true; }
                } else { autoOpened = false; }
                $(this).closest('.acu-control-row').addClass('acu-active-control');
                transparencyTimer = setTimeout(() => { dialog.addClass('acu-transparent-mode'); }, 150);
                $el.on('pointerup pointercancel', end);
            });
            $el.on('change', end);
