        const html = `
            <div class="acu-quick-view-overlay">
                <div class="acu-quick-view-card acu-theme-${config.theme}">
                     <div class="acu-quick-view-header">
                        <span><i class="fa-solid ${getIconForTableName(tableName)}"></i> ${row[1] || '详情'}</span>
