{{// 注释：
如果你要玩第二人称 或者 自己的user为主角的玩法，直接不用改
如果你想要类似第三人称上帝视角，视野平均分配给每个角色，或者你想让你的角色不作为故事的主角，又或者你想小猫之神按你给出的故事走向继续剧情，那么你可以把下面的“{{user}}”改成一个和剧情 【完全无关】 的名字
前面的【用户：】和前后的两个杠不要动，只改{{user}}的部分
}}
|用户：{{user}}|

{"ChatSquash":{"enabled":true,"separate_chat_history":false,"parse_clewd":false,"role":"assistant","stop_string":"["<end>", "<ctrl", "<thought>"]","user_prefix":"</小猫之神世界书处理>

|{{user}}|
","user_suffix":"<小猫之神世界书处理>","char_prefix":"</小猫之神世界书处理>

|游戏剧情|
","char_suffix":"<end><小猫之神世界书处理>","prefix_system":"","suffix_system":"","enable_squashed_separator":true,"squashed_separator_regex":false,"squashed_separator_string":"<|sep|>","squashed_post_script_enable":true,"squashed_post_script":"content => {
  const usernameRegex = /\|用户：(.*?)\|/;

  const usernameMatches = content.match(usernameRegex);
  let username = '用户';
  if (usernameMatches && usernameMatches.length > 1) {
    username = usernameMatches[1];
  }

  content = content.replace(usernameRegex, '');

  // 匹配所有 <小猫之神世界书处理>...</小猫之神世界书处理> 的内容
  const regex = /<小猫之神世界书处理>([\s\S]*?)<\/小猫之神世界书处理>/g;

  // 先提取所有匹配内容
  const matches = [];
  let match;
  while ((match = regex.exec(content)) !== null) {
    matches.push(match[1]);
  }

  // 去掉原来的标签和内容
  const withoutTags = content.replace(regex, '');

  // 分离最后两组和之前的
  const lastTwoMatches = matches.slice(-3); // 最后两组
  const previousMatches = matches.slice(0, -3); // 之前的所有

  const lastTwoContent = lastTwoMatches.join('\n').trim();
  const previousContent = previousMatches.join('\n').trim();

  // 把提取的内容追加到相应位置
  let result = withoutTags
    .replaceAll(
      '<|前置世界书|>',
      previousContent ? '\n\n|额外设定| \n' + previousContent : '',
    )
    .replaceAll(
      '|小猫之神_世界书|',
      lastTwoContent ? '\n\n|额外信息&要求| \n' + lastTwoContent : '',
    ).trim();

  const deleteRegex = /\|delete\|[\s\S]*?\|\/delete\|/g;
  result = result.replace(deleteRegex, '');

  let prev = null; // 'cat' | 'user' | null
  const re = /[\n]*\|(小猫之神|用户)\|/g;

  // 处理 summary 标签，插入剧情总结标记
  // 找到所有独立的 <summary>（前面没有 details）
  const summaryPositions = [];
  const summaryRegex = /<summary>/g;
  let summaryMatch;

  while ((summaryMatch = summaryRegex.exec(result)) !== null) {
    const index = summaryMatch.index;
    // 检查前面是否紧跟着 details>（排除 <details><summary> 的情况）
    const before = result.substring(Math.max(0, index - 10), index);
    if (!/details>\s*$/.test(before)) {
      summaryPositions.push(index);
    }
  }

  // 排除最后四个，只处理前面的
  const positionsToProcess = summaryPositions.slice(0, -3);

  // 从后往前处理，避免索引偏移问题
  for (let i = positionsToProcess.length - 1; i >= 0; i--) {
    const pos = positionsToProcess[i];
    const insertPos = pos + '<summary>'.length;
    const insertText = `\n---第${i + 1}段剧情总结---`;
    result = result.substring(0, insertPos) + insertText + result.substring(insertPos);
  }

  return String(result).replace(re, (_, who) => {
    const isCat = who === '小猫之神';
    let replacement;

    if (isCat) {
      replacement = `\n<role>soliumbra\n`;
      prev = 'cat';
    } else {
      const prefix = prev === 'cat' ? '<end>' : '';
      replacement = `${prefix}\n<role>${username}\n`;
      prev = 'user';
    }

    return replacement;
  });
};
